interface.signature:
class ProgressionSystem {
  calculateXP(score: number): number
  checkLevelUp(currentXP: number, currentLevel: number): { leveledUp: boolean, newLevel: number }
  getXPForNextLevel(level: number): number
  getXPProgress(currentXP: number, level: number): number
  calculateSvitlyachky(finalCoziness: number, survived: boolean): number  // NEW METHOD
}

interface GameStateContextValue {
  gameState: GameState  // includes coziness: number (0-100)
  // ... other properties
  // gameState.coziness provides final coziness for currency calculation
}

function saveGameState(state: ProgressionState): void
function loadGameState(): ProgressionState | null
// ProgressionState includes svitlyachky property for currency persistence

const SVITLYACHKY_REWARDS = {
  base: 1,      // For surviving (Затишок > 0 at end)
  bonus_50: 1,  // If final Затишок ≥ 50
  bonus_80: 1,  // If final Затишок ≥ 80
}
const MAX_SVITLYACHKY_PER_EVENING = 3
